def rle_decode(s: str) -> str:
    result = []
    i = 0

    while i < len(s):
        if s[i] == "#":
            raise ValueError("'#' must be preceded by a character")

        if i + 1 < len(s) and s[i + 1] == "#":
            j = i + 2

            if j >= len(s) or not ("0" <= s[j] <= "9"):
                raise ValueError("run marker must be followed by digits")

            while j < len(s) and "0" <= s[j] <= "9":
                j += 1

            count = int(s[i + 2:j])
            if count < 4:
                raise ValueError("run length must be at least 4")

            result.append(s[i] * count)
            i = j
        else:
            result.append(s[i])
            i += 1

    return "".join(result)
